using System;using System.Linq;using System.Text;using System.IO;using Verse;using Verse.AI;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{
public static string Run(){foreach(var w in Find.WindowStack.Windows.OfType<Dialog_MiniGame>().ToList())w.Close();TogetherMatch.Reset();var map=Find.CurrentMap;var p=(Pawn)Host.State["rostra"];var o=(Pawn)Host.State["anya"];var q=(Pawn)Host.State["ineligible"];foreach(var x in new[]{p,o,q}){x.drafter.Drafted=false;foreach(var h in x.health.hediffSet.hediffs.Where(h=>h.def==HediffDefOf.Anesthetic).ToList())x.health.RemoveHediff(h);x.needs.food.CurLevelPercentage=1;x.needs.rest.CurLevelPercentage=1;for(int h=0;h<24;h++)x.timetable.SetAssignment(h,TimeAssignmentDefOf.Anything);}
var names=new[]{"PokerTable","HorseshoesPin","HoopstoneRing"};var boards=new Thing[3];for(int i=0;i<3;i++){var def=DefDatabase<ThingDef>.GetNamed(names[i]);boards[i]=ThingMaker.MakeThing(def,def.MadeFromStuff?ThingDefOf.WoodLog:null);boards[i].SetFaction(Faction.OfPlayer);GenSpawn.Spawn(boards[i],new IntVec3(132+i*10,0,110),map);if(i==0)foreach(var cell in GenAdjFast.AdjacentCellsCardinal(boards[i])){if(!cell.Standable(map))continue;var c=ThingMaker.MakeThing(ThingDefOf.DiningChair,ThingDefOf.WoodLog);c.SetFaction(Faction.OfPlayer);GenSpawn.Spawn(c,cell,map);}}
Host.State["arenaBoards"]=boards;int index=0,stage=0,start=Find.TickManager.TicksGame;string log=Host.Root+"/reservation-suite.txt";File.WriteAllText(log,"Actual vanilla JoyGiver and JobDriver under two-player reservation.\n");
Action begin=()=>{var b=boards[index];foreach(var x in new[]{p,o,q}){x.jobs.EndCurrentJob(JobCondition.InterruptForced);x.Position=b.Position+new IntVec3(-4,0,-4+(x==p?0:x==o?1:2));x.Notify_Teleported();if(x.needs.joy!=null)x.needs.joy.CurLevelPercentage=.1f;}GameEntry.Commit(b.TryGetComp<CompMiniGame>().Game,b,p,o,1,false);start=Find.TickManager.TicksGame;stage=0;};begin();
Host.Watch=()=>{int t=Find.TickManager.TicksGame;var b=boards[index];var game=b.TryGetComp<CompMiniGame>().Game;var dialog=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(stage==0&&(dialog!=null||t-start>1200)){File.AppendAllText(log,game.defName+" pairOpen="+(dialog!=null)+" maxPawns="+Together.SeatCount(b)+" thirdCanReserve="+q.CanReserve(b,Together.SeatCount(b),0)+"\n");var others=map.listerThings.AllThings.Where(x=>x!=b&&x.TryGetComp<CompMiniGame>()?.Game==game).ToList();foreach(var other in others)other.SetForbidden(true,false);var giver=DefDatabase<JoyGiverDef>.AllDefsListForReading.FirstOrDefault(d=>d.jobDef==game.vanillaJob);var job=giver?.Worker.TryGiveJob(q);File.AppendAllText(log,"vanillaGiver="+giver+" job="+job+"\n");if(job!=null)q.jobs.TryTakeOrderedJob(job);foreach(var other in others)other.SetForbidden(false,false);stage=1;start=t;}else if(stage==1&&t-start>180){File.AppendAllText(log,"after180 third="+q.CurJob+" pair="+p.CurJobDef+","+o.CurJobDef+"\n");dialog?.Close();TogetherMatch.Reset();foreach(var x in new[]{p,o,q})x.jobs.EndCurrentJob(JobCondition.InterruptForced);index++;if(index>=boards.Length){Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}else begin();}};
Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Running poker/horseshoes/hoopstone reservation coexistence on actual furniture.";}}
